import{_ as a,o as l,c as o,af as e}from"./chunks/framework.Ce1DK3eM.js";const p=JSON.parse('{"title":"VMware Workstation使用教程","description":"","frontmatter":{"title":"VMware Workstation使用教程"},"headers":[],"relativePath":"vmware17.6.3_win.md","filePath":"vmware17.6.3_win.md"}'),i={name:"vmware17.6.3_win.md"};function r(d,t,s,n,h,c){return l(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1791009149310"},[...t[0]||(t[0]=[e(`<h2 id="一、前置准备" tabindex="-1">一、前置准备 <a class="header-anchor" href="#一、前置准备" aria-label="Permalink to &quot;一、前置准备&quot;">​</a></h2><h3 id="_1-硬件与-bios-虚拟化开关" tabindex="-1">1. 硬件与 BIOS 虚拟化开关 <a class="header-anchor" href="#_1-硬件与-bios-虚拟化开关" aria-label="Permalink to &quot;1. 硬件与 BIOS 虚拟化开关&quot;">​</a></h3><ul><li>CPU 必须开启虚拟化：<code>Intel VT-x</code> / <code>AMD-V</code>，在主板 BIOS/UEFI 打开</li><li>Windows 宿主：关闭<code>Hyper-V</code>（如果开启会导致 VMware 无法启动）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 管理员CMD，关闭Hyper-V，重启生效</span></span>
<span class="line"><span>bcdedit /set hypervisorlaunchtype off</span></span></code></pre></div><ul><li>内存建议：宿主至少 16G，分配给虚拟机不要超过物理内存一半</li></ul><h3 id="_2-软件下载" tabindex="-1">2. 软件下载 <a class="header-anchor" href="#_2-软件下载" aria-label="Permalink to &quot;2. 软件下载&quot;">​</a></h3><p>博通官网下载 VMware Workstation Pro，<strong>现已免费商用 / 个人使用，无需密钥</strong>。 准备好操作系统 ISO 镜像（Windows / Linux）。</p><h2 id="二、安装-vmware-workstation" tabindex="-1">二、安装 VMware Workstation <a class="header-anchor" href="#二、安装-vmware-workstation" aria-label="Permalink to &quot;二、安装 VMware Workstation&quot;">​</a></h2><ol><li>运行安装包，接受许可协议</li><li>选择安装路径，建议不要放 C 盘</li><li>可选：勾选增强型键盘驱动（虚拟机捕获键盘）</li><li>下一步完成安装，重启电脑。</li></ol><h2 id="三、新建虚拟机-标准向导" tabindex="-1">三、新建虚拟机（标准向导） <a class="header-anchor" href="#三、新建虚拟机-标准向导" aria-label="Permalink to &quot;三、新建虚拟机（标准向导）&quot;">​</a></h2><ol><li>首页点击 <strong>创建新的虚拟机</strong></li><li>选择「典型 (推荐)」→ 下一步</li><li>安装来源：<strong>安装程序光盘映像文件 (iso)</strong>，选中你的系统 ISO</li></ol><blockquote><p>也可以选择「稍后安装操作系统」，手动配置硬件（推荐进阶用户）</p></blockquote><ol start="4"><li>选择客户机操作系统：Windows / Linux，选择对应版本</li><li>设置虚拟机名称，选择虚拟机文件存放目录（剩余空间充足的盘）</li><li>指定磁盘容量： <ul><li>最大磁盘大小：Win10 建议≥60G，Ubuntu≥30G</li><li>推荐：<strong>将虚拟磁盘存储为单个文件</strong>，性能更好</li></ul></li><li>点击「自定义硬件」，修改资源： <ul><li>内存：Win10 推荐 4G，Linux 最小 2G</li><li>处理器：核心数，不超过宿主物理核心总数</li><li>CD/DVD：确认绑定 ISO 镜像</li><li>网络适配器：默认 NAT</li></ul></li><li>关闭硬件窗口 → 完成。</li></ol><h2 id="四、虚拟机硬件网络模式说明" tabindex="-1">四、虚拟机硬件网络模式说明 <a class="header-anchor" href="#四、虚拟机硬件网络模式说明" aria-label="Permalink to &quot;四、虚拟机硬件网络模式说明&quot;">​</a></h2><p>表格</p><table tabindex="0"><thead><tr><th>模式</th><th>作用</th><th>适用场景</th></tr></thead><tbody><tr><td>NAT（默认）</td><td>虚拟机共享主机 IP，可上网，外部无法主动访问虚拟机</td><td>日常上网、开发，推荐新手</td></tr><tr><td>桥接模式</td><td>虚拟机和宿主机在同一局域网，独立 IP，局域网设备可访问</td><td>局域网测试、服务器调试</td></tr><tr><td>仅主机 (Host-only)</td><td>虚拟机和宿主机私有网络，<strong>不能访问外网</strong></td><td>隔离测试、内网实验</td></tr></tbody></table><h2 id="五、开机安装系统-安装-vmware-tools" tabindex="-1">五、开机安装系统 + 安装 VMware Tools <a class="header-anchor" href="#五、开机安装系统-安装-vmware-tools" aria-label="Permalink to &quot;五、开机安装系统 + 安装 VMware Tools&quot;">​</a></h2><blockquote><p>VMware Tools 是虚拟机驱动包，<strong>必须安装</strong>，实现：复制粘贴、文件拖拽、自动适配分辨率、鼠标自由进出虚拟机。</p></blockquote><ol><li>点击「开启此虚拟机」，点击窗口捕获鼠标（<code>Ctrl+Alt</code>释放鼠标）</li><li>按照 ISO 引导，安装客户机操作系统</li><li>系统安装完成后，在 VM 顶部菜单：<code>虚拟机 → 安装VMware Tools</code></li><li>虚拟机内会挂载 Tools 光盘，运行安装程序，一路下一步，重启虚拟机。</li></ol><blockquote><p>Linux（Ubuntu/Debian）可命令行安装：</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install open-vm-tools open-vm-tools-desktop -y</span></span></code></pre></div><h2 id="六、核心常用功能" tabindex="-1">六、核心常用功能 <a class="header-anchor" href="#六、核心常用功能" aria-label="Permalink to &quot;六、核心常用功能&quot;">​</a></h2><h3 id="_1-快照-snapshot-⭐非常重要" tabindex="-1">1. 快照（Snapshot）⭐非常重要 <a class="header-anchor" href="#_1-快照-snapshot-⭐非常重要" aria-label="Permalink to &quot;1. 快照（Snapshot）⭐非常重要&quot;">​</a></h3><blockquote><p>快照：保存虚拟机当前完整状态，随时回滚，测试、调试必备。 ⚠️ 快照不是备份！大量快照会占用巨大磁盘空间，长期环境不要依赖快照。</p></blockquote><p>操作：</p><ol><li>虚拟机<strong>关机 / 开机状态都可以</strong>（关机快照更稳定）</li><li>顶部菜单 <code>虚拟机 → 快照 → 拍摄快照</code></li><li>填写名称 + 备注（例如：纯净系统，未装软件）</li><li>需要恢复：<code>快照管理器</code>，选中快照，点击「转到快照」，虚拟机直接恢复到当时状态。</li></ol><h3 id="_2-共享文件夹-宿主机-↔-虚拟机互传文件" tabindex="-1">2. 共享文件夹（宿主机 ↔ 虚拟机互传文件） <a class="header-anchor" href="#_2-共享文件夹-宿主机-↔-虚拟机互传文件" aria-label="Permalink to &quot;2. 共享文件夹（宿主机 ↔ 虚拟机互传文件）&quot;">​</a></h3><ol><li>虚拟机<strong>必须关机</strong>，不能开机修改</li><li><code>虚拟机 → 设置 → 选项 → 共享文件夹</code></li><li>选择「总是启用」，点击「添加」，选择宿主机本地文件夹</li><li>设置权限：只读 / 可读写</li><li>Windows 虚拟机：共享目录在 <code>网络位置 → VMware Shared Folders</code></li><li>Linux 虚拟机：默认 <code>/mnt/hgfs/</code></li></ol><h3 id="_3-虚拟机克隆" tabindex="-1">3. 虚拟机克隆 <a class="header-anchor" href="#_3-虚拟机克隆" aria-label="Permalink to &quot;3. 虚拟机克隆&quot;">​</a></h3><blockquote><p>快速复制一台一模一样的虚拟机，适合批量部署。</p></blockquote><ol><li>虚拟机<strong>完全关机</strong></li><li><code>虚拟机 → 管理 → 克隆</code></li><li>源：当前虚拟机状态</li><li>克隆类型： <ul><li><strong>链接克隆</strong>：体积小，依赖原虚拟机，原虚拟机删除则克隆失效，适合临时测试</li><li><strong>完整克隆</strong>：独立完整副本，体积大，可以单独移动、迁移，生产推荐。</li></ul></li></ol><h3 id="_4-虚拟机迁移" tabindex="-1">4. 虚拟机迁移 <a class="header-anchor" href="#_4-虚拟机迁移" aria-label="Permalink to &quot;4. 虚拟机迁移&quot;">​</a></h3><p>完整克隆或者直接复制虚拟机整套文件夹，在另一台 VMware 打开「打开虚拟机」选中<code>.vmx</code>文件即可。</p><h2 id="七、快捷键汇总" tabindex="-1">七、快捷键汇总 <a class="header-anchor" href="#七、快捷键汇总" aria-label="Permalink to &quot;七、快捷键汇总&quot;">​</a></h2><p>表格</p><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl + Alt</code></td><td>释放鼠标，退出虚拟机窗口</td></tr><tr><td><code>Ctrl + G</code></td><td>捕获鼠标，进入虚拟机</td></tr><tr><td><code>Ctrl + Pause</code></td><td>虚拟机暂停</td></tr><tr><td><code>Ctrl + B</code></td><td>开机</td></tr><tr><td><code>Ctrl + E</code></td><td>关机</td></tr><tr><td><code>Ctrl + Shift + S</code></td><td>拍摄快照</td></tr></tbody></table><h2 id="八、常见问题排错" tabindex="-1">八、常见问题排错 <a class="header-anchor" href="#八、常见问题排错" aria-label="Permalink to &quot;八、常见问题排错&quot;">​</a></h2><ol><li><strong>此主机不支持 Intel VT-x</strong><ul><li>进入 BIOS 开启虚拟化；Windows 关闭 Hyper-V、WSL2 内核隔离。</li></ul></li><li><strong>虚拟机黑屏</strong><ul><li>虚拟机设置 → 显示器，取消「加速 3D 图形」；更新 VMware Tools。</li></ul></li><li><strong>复制粘贴 / 拖拽失效</strong><ul><li>确认 VMware Tools 已正常安装并运行；重启虚拟机。</li></ul></li><li><strong>NAT 模式虚拟机无法上网</strong><ul><li>顶部菜单「编辑 → 虚拟网络编辑器」，重置 NAT 和 DHCP 服务，重启 VMware。</li></ul></li></ol><h2 id="九、最佳实践建议" tabindex="-1">九、最佳实践建议 <a class="header-anchor" href="#九、最佳实践建议" aria-label="Permalink to &quot;九、最佳实践建议&quot;">​</a></h2><ol><li>虚拟机文件不要放在系统盘，防止 C 盘爆满。</li><li>测试环境大量快照用完及时删除，避免磁盘膨胀。</li><li>重要环境使用<strong>完整克隆</strong>做备份，不要只依赖快照。</li><li>做开发推荐 NAT；局域网服务测试用桥接；病毒 / 恶意代码测试使用 Host-only 隔离网络。</li></ol>`,40)])])}const b=a(i,[["render",r]]);export{p as __pageData,b as default};
